mapper.select:

WHERE scope = #{scope}
  AND tenant_id IS NOT DISTINCT FROM #{tenantId}::uuid
  AND audit_id = #{auditId}::uuid


WHERE scope = #{scope}
  AND tenant_id IS NOT DISTINCT FROM #{tenantId}::uuid

  AND resource_kind = #{resourceKind}


  AND resource_id = #{resourceId}


  AND event_type = #{eventType}


  AND operator_id = #{operatorId}


  AND created_at >= #{fromTime}::timestamptz


  AND created_at <= #{toTime}::timestamptz


  AND (created_at < #{cursorCreatedAt}::timestamptz
       OR (created_at = #{cursorCreatedAt}::timestamptz AND audit_id < #{cursorAuditId}::uuid))

ORDER BY created_at DESC, audit_id DESC
LIMIT #{limitPlusOne}
